using System;
using System.Collections.Generic;
using UnityEngine;
namespace Deepsea { public sealed partial class SeaSeamlessWorldAndNauticalUIV29 {
 sealed class NativeRestore {public MeshFilter filter;public Mesh mesh;public Renderer renderer;public Material[] materials;}
 readonly List<NativeRestore> nativeRestoreV30=new List<NativeRestore>();
 float EcoCoverV30(Vector3 p){if(p.y-SeaLifeRuntime.Sea<.45f)return 0;float n=.5f+.30f*Mathf.Sin(p.x*.19f+Mathf.Cos(p.z*.17f)*2)+.20f*Mathf.Cos(p.z*.31f-p.x*.23f);return Mathf.SmoothStep(0,1,Mathf.InverseLerp(.45f,2.35f,p.y-SeaLifeRuntime.Sea+(n-.5f)*.85f))*Mathf.SmoothStep(0,1,Mathf.InverseLerp(-2,9,ShoreX(p.z)-p.x+(n-.5f)*4));}
 void ApplyNativeEcologyV30(){var root=GameObject.Find("EN_MistCapeShowcase");if(root==null)return;var mats=new Dictionary<Material,Material>();foreach(var f in UnityEngine.Object.FindObjectsOfType<MeshFilter>()){string n=f.name;var r=f.GetComponent<Renderer>();if(r==null||!r.enabled||f.sharedMesh==null||!f.gameObject.activeInHierarchy||n.Contains("Leaves"))continue;if(f.transform.IsChildOf(worldRoot))continue;bool broadSand=r.sharedMaterial!=null&&r.sharedMaterial.name.IndexOf("Sand",StringComparison.OrdinalIgnoreCase)>=0&&r.bounds.size.x>12&&r.bounds.size.z>12&&r.bounds.min.x<-8;if(!(broadSand||n.Contains("FineShore")||n.Contains("Land_Rock")||n.Contains("Inland")||n.Contains("Headland")||n.Contains("MapleFoot")||n.Contains("Substrate")))continue;nativeRestoreV30.Add(new NativeRestore{filter=f,mesh=f.sharedMesh,renderer=r,materials=r.sharedMaterials});var mesh=Instantiate(f.sharedMesh);mesh.name=f.sharedMesh.name+"_V30_Eco";var v=mesh.vertices;var c=new Color[v.Length];for(int i=0;i<v.Length;i++)c[i]=new Color(EcoCoverV30(f.transform.TransformPoint(v[i])),0,0,1);mesh.colors=c;_owned.Add(mesh);f.sharedMesh=mesh;var slots=r.sharedMaterials;for(int i=0;i<slots.Length;i++){Material m;if(!mats.TryGetValue(slots[i],out m)){m=new Material(slots[i]);m.name=slots[i].name+"_V30_Eco";m.shader=unifiedTerrainMat.shader;m.SetFloat("_Mode",1);m.SetTexture("_SandMap",unifiedTerrainMat.GetTexture("_SandMap"));m.SetTexture("_CoverMap",unifiedTerrainMat.GetTexture("_CoverMap"));mats[slots[i]]=m;_owned.Add(m);}slots[i]=m;}r.sharedMaterials=slots;}}
 void RestoreNativeEcologyV30(){foreach(var b in nativeRestoreV30){if(b.filter!=null)b.filter.sharedMesh=b.mesh;if(b.renderer!=null)b.renderer.sharedMaterials=b.materials;}nativeRestoreV30.Clear();}
 [Serializable]sealed class EcoDiagnostic {public string name,mesh,shader,material;public float mode,minx,minz,miny,maxx,maxz,maxy;public int vertices,green,mixed;}
 [Serializable]sealed class EcoDiagnostics {public List<EcoDiagnostic> meshes=new List<EcoDiagnostic>();}
 void DumpEcoV30(){var data=new EcoDiagnostics();foreach(var f in UnityEngine.Object.FindObjectsOfType<MeshFilter>()){var r=f.GetComponent<Renderer>();if(r==null||!r.enabled||f.sharedMesh==null||r.sharedMaterial==null)continue;var mat=r.sharedMaterial;string shader=mat.shader.name;var b=r.bounds;var d=new EcoDiagnostic{name=f.name,mesh=f.sharedMesh.name,shader=shader,material=mat.name,mode=mat.HasProperty("_Mode")?mat.GetFloat("_Mode"):-1,minx=b.min.x,maxx=b.max.x,minz=b.min.z,maxz=b.max.z,miny=b.min.y,maxy=b.max.y,vertices=f.sharedMesh.vertexCount};foreach(var c in f.sharedMesh.colors){if(c.r>.8f)d.green++;else if(c.r>.02f)d.mixed++;}data.meshes.Add(d);}System.IO.File.WriteAllText(System.IO.Path.Combine(evidence,"terrain-materials.json"),JsonUtility.ToJson(data,true));}
 void CheckUnifiedWorldV30(){
  if(!IsV30)return;DumpEcoV30();var shelf=worldRoot.Find("V29_ContinuousContinentalShelf").GetComponent<MeshFilter>().sharedMesh;Check(worldRoot.Find("V29_WesternLandContinuation")==null&&shelf.colors.Length==shelf.vertexCount,"v30 one connected terrain mesh carries eco vertex colors");
  int grass=0,sand=0,mix=0;var v=shelf.vertices;var c=shelf.colors;bool underwaterSand=true;for(int i=0;i<c.Length;i++){if(c[i].r>.98f)grass++;else if(c[i].r<.02f)sand++;else mix++;if(v[i].y<SeaLifeRuntime.Sea+.45f&&c[i].r>.001f)underwaterSand=false;}Check(grass>1000&&sand>1000&&mix>100&&underwaterSand,"v30 sand, mixed cover and inland grass exist; submerged vertices stay sand");
  bool edge=true;foreach(float x in new[]{-155f,-80,0,80,195})foreach(float z in new[]{-165f,175})edge &= Mathf.Abs(HeightAt(x,z)-(SeaLifeRuntime.Sea-14))<.005f;foreach(float z in new[]{-165f,-80,0,80,175})foreach(float x in new[]{-155f,195})edge &= Mathf.Abs(HeightAt(x,z)-(SeaLifeRuntime.Sea-14))<.005f;Check(edge,"v30 all terrain borders equal background floor without a depth step");
  Check(HeightAt(ShoreX(70)-20,70)>SeaLifeRuntime.Sea+2&&HeightAt(ShoreX(-70)-20,-70)>SeaLifeRuntime.Sea+2,"v30 north and south have broad above-water inland shoulders");Check(nativeRestoreV30.Count>0,"native shoreline meshes receive runtime-only matching eco cover");bool substrates=true;int substrateCount=0;foreach(var b in nativeRestoreV30)if(b.filter.name.Contains("Substrate")){substrateCount++;substrates &= b.filter.sharedMesh.name.EndsWith("_V30_Eco")&&b.renderer.sharedMaterial.shader==unifiedTerrainMat.shader;}Check(substrates&&substrateCount>=6,"all six legacy substrate strips use the unified ecological transition");Check(materialText.text.Contains("黄铜"),"v30 brass remains visible in material inventory");int gridCount;Check(bay.GridCheckV30(out gridCount),"v30 every visible grid cell meets shallow-depth and slope limits");Check(pills[3].text.StartsWith("潮汐石")&&pills[4].text.StartsWith("珊瑚苗"),"v30 stone and coral seed have separate resource pills");Check(cardRects[bay.SelectedV29].anchoredPosition.y>-88&&cardRects[bay.SelectedV29].localScale.x>1.02f,"v30 active blueprint visibly lifts and scales");
 }
}}

namespace Deepsea {public sealed partial class SeaBayExpansionAndBuildSpaceV28 {public bool GridCheckV30(out int count){var v=gridRoot.GetComponentInChildren<MeshFilter>().sharedMesh.vertices;count=v.Length/16;for(int i=0;i<v.Length;i+=16){var p=v[i]+new Vector3(.99f,-.035f,.99f);if(!V30FlatCell(p))return false;}return count>0;}}}
